#!/usr/bin/env bash
# PreToolUse hook: check-compiled-files   (BLOCKING, fail-open on parse error)
#
# Blocks hand edits of generated files. Hand edits to generated output are silently overwritten
# on the next build, or worse, drift from their source. Two detection modes:
#   1. Marker mode (automatic): the EXISTING file starts (first 10 lines) with a generated-file
#      marker such as "DO NOT EDIT", "@generated", "auto-generated", "autogenerated",
#      "generated by".
#   2. Pattern mode (configurable): the path matches CLAUDE_COMPILED_FILES_REGEX.
#
# Event / matcher : PreToolUse / Edit|Write            (timeout 3)
# Exit codes      : 0 allow, 2 block.
# Env:
#   CLAUDE_COMPILED_FILES_REGEX  extended regex on the file path
#                                (default: lockfiles and minified bundles:
#                                 (package-lock\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?|\.min\.(js|css))$ )
#   CLAUDE_COMPILED_FILES_HINT   sentence appended to the message, say how to regenerate the file
#                                (default: "Edit the source and run the generator instead.")
#   CLAUDE_ALLOW_COMPILED_EDIT=1 bypass for the session.

[[ "${CLAUDE_ALLOW_COMPILED_EDIT:-0}" == "1" ]] && exit 0

REGEX="${CLAUDE_COMPILED_FILES_REGEX:-(package-lock\.json|pnpm-lock\.yaml|yarn\.lock|bun\.lockb?|\.min\.(js|css))$}"
HINT="${CLAUDE_COMPILED_FILES_HINT:-Edit the source and run the generator (or the package manager) instead.}"

INPUT="$(cat)"
FILE="$(printf '%s' "$INPUT" | python3 -c 'import json,sys; print(json.load(sys.stdin).get("tool_input",{}).get("file_path",""))' 2>/dev/null)"
[[ -n "$FILE" ]] || exit 0

if printf '%s' "$FILE" | grep -qE "$REGEX"; then
  echo "BLOCKED: $FILE matches the generated-files pattern. $HINT (bypass: CLAUDE_ALLOW_COMPILED_EDIT=1)" >&2
  exit 2
fi

if [[ -f "$FILE" ]] && head -n 10 "$FILE" 2>/dev/null | grep -qiE 'do not edit|@generated|auto-?generated|generated by'; then
  echo "BLOCKED: $FILE declares itself as generated in its header. $HINT (bypass: CLAUDE_ALLOW_COMPILED_EDIT=1)" >&2
  exit 2
fi

exit 0
